import{_ as a,o as s,c as e,aQ as i}from"./chunks/framework.C8WmN7-d.js";const k=JSON.parse('{"title":"OpenWrt 常用插件","description":"","frontmatter":{},"headers":[],"relativePath":"ops/openwrt/plugins/index.md","filePath":"ops/openwrt/plugins/index.md","lastUpdated":1773046209000}'),d={name:"ops/openwrt/plugins/index.md"};function l(n,t,h,p,o,r){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="openwrt-常用插件" tabindex="-1">OpenWrt 常用插件 <a class="header-anchor" href="#openwrt-常用插件" aria-label="Permalink to &quot;OpenWrt 常用插件&quot;">​</a></h1><p>本文汇总 OpenWrt 上常用第三方/额外插件的<strong>包名</strong>与用途，便于在「系统 → 软件包」或 SSH 下用 <code>opkg</code> 安装。不同固件（官方 OpenWrt、ImmortalWrt、自编译等）软件源可能不同，部分插件需先添加对应软件源或从 GitHub 安装。</p><div class="tip custom-block"><p class="custom-block-title">软件包对照</p><p>不确定包名或依赖时，可参考论坛整理帖：<a href="https://www.right.com.cn/forum/forum.php?mod=viewthread&amp;tid=8387547&amp;highlight=%E8%BD%AF%E4%BB%B6%E5%8C%85" target="_blank" rel="noreferrer">OpenWrt 软件包对照表</a>（恩山）。</p></div><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to &quot;安装方式&quot;">​</a></h2><ul><li><strong>LuCI 界面</strong>：登录后台 → <strong>系统 → 软件包</strong> → 更新列表后搜索包名，安装。</li><li><strong>SSH 命令行</strong>：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">包</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div></li></ul><p>安装后若为 LuCI 插件，通常会在「服务」或「网络」等菜单下出现新入口；部分需刷新页面或重新登录。</p><hr><h2 id="代理与科学上网" tabindex="-1">代理与科学上网 <a class="header-anchor" href="#代理与科学上网" aria-label="Permalink to &quot;代理与科学上网&quot;">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>包名（示例）</th><th>说明</th></tr></thead><tbody><tr><td>OpenClash</td><td><code>luci-app-openclash</code></td><td>常用 Clash 内核 LuCI 管理界面，需在界面内下载/选择内核。</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>OpenClash 等代理插件多数不在官方源，需使用 ImmortalWrt、OpenWrt 第三方固件自带源，或从开发者 GitHub Release 下载对应架构的 ipk 安装。</p></div><hr><h2 id="动态-dns-ddns" tabindex="-1">动态 DNS（DDNS） <a class="header-anchor" href="#动态-dns-ddns" aria-label="Permalink to &quot;动态 DNS（DDNS）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>包名（示例）</th><th>说明</th></tr></thead><tbody><tr><td>DDNS Go</td><td><code>luci-app-ddns-go</code>、<code>luci-i18n-ddns-go-zh-cn</code></td><td>动态 DNS 客户端，支持多服务商；中文语言包可选。</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-app-ddns-go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-i18n-ddns-go-zh-cn</span></span></code></pre></div><hr><h2 id="广告过滤" tabindex="-1">广告过滤 <a class="header-anchor" href="#广告过滤" aria-label="Permalink to &quot;广告过滤&quot;">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>包名（示例）</th><th>说明</th></tr></thead><tbody><tr><td>AdBlock</td><td><code>luci-app-adblock</code>、<code>luci-i18n-adblock-zh-cn</code></td><td>基于域名/列表的广告拦截，可订阅规则。</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-app-adblock</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-i18n-adblock-zh-cn</span></span></code></pre></div><hr><h2 id="vpn" tabindex="-1">VPN <a class="header-anchor" href="#vpn" aria-label="Permalink to &quot;VPN&quot;">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>包名（示例）</th><th>说明</th></tr></thead><tbody><tr><td>OpenVPN 服务端</td><td><code>luci-app-openvpn-server</code>、<code>luci-i18n-openvpn-server-zh-cn</code></td><td>在路由上提供 OpenVPN 服务端，便于远程访问内网。</td></tr><tr><td>Tailscale</td><td><code>luci-app-tailscale</code></td><td>Tailscale 组网客户端，可与其它设备组成虚拟局域网。</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># OpenVPN 服务端</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-app-openvpn-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-i18n-openvpn-server-zh-cn</span></span></code></pre></div><p>Tailscale 需根据固件源安装，部分需从 <a href="https://github.com/tailscale/tailscale/wiki/OpenWrt" target="_blank" rel="noreferrer">Tailscale OpenWrt</a> 等渠道获取 ipk。</p><hr><h2 id="界面与主题" tabindex="-1">界面与主题 <a class="header-anchor" href="#界面与主题" aria-label="Permalink to &quot;界面与主题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>包名（示例）</th><th>说明</th></tr></thead><tbody><tr><td>Argon 主题配置</td><td><code>luci-app-argon-config</code></td><td>为 Argon 主题提供背景、透明度等 LuCI 配置。</td></tr></tbody></table><p>主题本身通常为 <code>luci-theme-argon</code>，与配置插件分开安装。</p><hr><h2 id="工具类" tabindex="-1">工具类 <a class="header-anchor" href="#工具类" aria-label="Permalink to &quot;工具类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>插件</th><th>包名（示例）</th><th>说明</th></tr></thead><tbody><tr><td>网络唤醒 (WOL)</td><td><code>luci-app-wol</code></td><td>在 LuCI 中通过局域网唤醒支持 WOL 的设备。</td></tr><tr><td>网页终端 (ttyd)</td><td><code>luci-app-ttyd</code></td><td>在浏览器中打开终端，无需 SSH 即可执行命令。</td></tr><tr><td>文件浏览</td><td><code>luci-app-filebrowser</code></td><td>提供简单的 Web 文件管理（部分固件为 filebrowser 等名称）。</td></tr><tr><td>实时监控 (Netdata)</td><td><code>luci-app-netdata</code></td><td>集成 Netdata，在 LuCI 中查看 CPU、内存、网络等实时图表。</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 示例：安装 WOL、网页终端</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-app-wol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luci-app-ttyd</span></span></code></pre></div><p>以上包名在不同版本/架构下可能略有差异，安装前建议在「软件包」中搜索关键词（如 <code>ttyd</code>、<code>wol</code>、<code>filebrowser</code>）确认后再装。</p><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>安装前先 <strong>更新列表</strong>（<code>opkg update</code> 或 界面「刷新」），再按包名安装。</li><li>遇到依赖错误时，先安装提示的依赖包，或换用带更多预装源的固件（如 ImmortalWrt）。</li><li>更多拨号、LAN、端口映射等基础配置见 <a href="/ops/openwrt/使用/">OpenWRT 使用</a>。</li></ul>`,35)])])}const b=a(d,[["render",l]]);export{k as __pageData,b as default};
